'use strict';
const data=window.OBSERVATORY_DATA;
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=value=>/^https?:\/\//i.test(value)?esc(value):'#';
let selectedState='',filtered=[];
const sources=new Map((data?.sources||[]).map(s=>[s.id,s]));
function displayDate(value){if(!value)return 'Event date unknown';if(value.length===4)return value;if(value.length===7){const [y,m]=value.split('-');return new Date(+y,+m-1,1).toLocaleDateString('en-GB',{month:'short',year:'numeric'});}return new Date(value+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});}
function renderStates(){const counts={};data.events.forEach(e=>counts[e.state]=(counts[e.state]||0)+1);$('states').innerHTML=['',...data.meta.states].map(s=>`<button type="button" class="state-button ${s===selectedState?'active':''}" data-state="${esc(s)}" aria-pressed="${s===selectedState}"><span>${esc(s||'All states')}</span><span class="state-count">${s?counts[s]||0:data.events.length}</span></button>`).join('');$('states').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedState=b.dataset.state;renderStates();render();});}
function evidence(e){return `<details><summary>Inspect evidence · ${e.source_count} source${e.source_count===1?'':'s'}</summary><div class="evidence"><dl><dt>Record</dt><dd>${esc(e.id)}</dd><dt>Event date basis</dt><dd>${esc(e.date_basis)}</dd><dt>Article date</dt><dd>${esc(displayDate(e.publication_date).replace('Event date unknown','Not established'))}</dd><dt>Date precision</dt><dd>${esc(e.date_precision)}</dd><dt>Confidence</dt><dd>${esc(e.confidence)}: confidence in this recorded action, not its outcomes</dd><dt>Limitations</dt><dd>${esc(e.limitations||'No additional record-specific limitation noted.')}</dd></dl>${e.source_ids.map(id=>{const s=sources.get(id);return `<div class="source"><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p class="source-meta">${esc(s.publisher)} · ${esc(s.source_type.replaceAll('_',' '))} · Retrieved ${esc(s.accessed_date)} · ${esc(s.retrieval_status)}</p><p>${esc(s.evidence_summary)}</p></div>`;}).join('')}</div></details>`;}
function render(){const q=$('search').value.toLowerCase().trim(),category=$('category').value,stage=$('stage').value,year=$('year').value,primary=$('primary').value;
filtered=data.events.filter(e=>(!selectedState||e.state===selectedState)&&(!q||[e.title,e.summary,e.state,e.initiative,e.limitations].join(' ').toLowerCase().includes(q))&&(!category||e.category===category)&&(!stage||e.stage===stage)&&(!year||(year==='unknown'?!e.event_date:e.event_date?.startsWith(year)))&&(!primary||e.has_primary_source===(primary==='yes')));
const order=$('sort').value;filtered.sort((a,b)=>{if(order==='state')return a.state.localeCompare(b.state)||(b.event_date||'').localeCompare(a.event_date||'');if(!a.event_date)return b.event_date?1:0;if(!b.event_date)return -1;return order==='oldest'?a.event_date.localeCompare(b.event_date):b.event_date.localeCompare(a.event_date);});
$('result-count').textContent=`${filtered.length} of ${data.events.length} reviewed milestones${selectedState?' · '+selectedState:''}`;
$('results').innerHTML=filtered.length?filtered.map(e=>`<article class="event"><div class="event-top"><span class="event-state">${esc(e.state)}</span><span>·</span><time>${esc(displayDate(e.event_date))}</time><span class="stage ${esc(e.stage)}">${esc(e.stage)}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p><div class="event-bottom"><span>${esc(e.category)} · ${e.has_primary_source?'Primary source available':'News sources only'}</span><a href="${safeUrl(e.source_url)}" target="_blank" rel="noopener noreferrer">${esc(e.source_name)} ↗</a></div>${evidence(e)}</article>`).join(''):'<div class="empty"><h3>No matching records</h3><p>Try a broader search or reset the filters. No matches does not mean no policy activity.</p></div>';
const params=new URLSearchParams();if(selectedState)params.set('state',selectedState);for(const id of ['search','category','stage','year','primary','sort'])if($(id).value&&!(id==='sort'&&$(id).value==='newest'))params.set(id,$(id).value);if(location.protocol!=='file:')history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+location.hash);
}
function exportFiltered(){const fields=['id','state','title','event_date','date_precision','date_basis','publication_date','category','stage','summary','source_name','source_url','limitations'];const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv='\ufeff'+[fields.map(cell).join(','),...filtered.map(e=>fields.map(f=>cell(e[f])).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='state-ai-policy-filtered.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
if(!data){$('results').innerHTML='<p class="empty">The evidence file could not be loaded. Download the CSV or reload this page.</p>';}else{
$('corpus').textContent=`${data.events.length} reviewed milestones · ${data.sources.length} source documents · ${data.meta.states.length} states`;
for(const id of ['category','stage']){const values=[...new Set(data.events.map(e=>e[id]))].sort();$(id).innerHTML+=values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}
const max=Math.max(...Object.values(data.meta.categories));$('categories').innerHTML=Object.entries(data.meta.categories).sort(([a],[b])=>a.localeCompare(b)).map(([c,n])=>`<div class="cat-row"><div class="cat-caption"><span>${esc(c)}</span><span>${n}</span></div><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div></div>`).join('');
const params=new URLSearchParams(location.search);selectedState=data.meta.states.includes(params.get('state'))?params.get('state'):'';for(const id of ['search','category','stage','year','primary','sort']){if(params.has(id))$(id).value=params.get(id);$(id).addEventListener(id==='search'?'input':'change',render);}
$('reset').onclick=()=>{selectedState='';['search','category','stage','year','primary'].forEach(id=>$(id).value='');$('sort').value='newest';renderStates();render();};$('export').onclick=exportFiltered;renderStates();render();}
